macro.command:
const actor = this.actor ?? this.parent ?? canvas.tokens.controlled[0]?.actor;
if (!actor) return ui.notifications.warn("Не найден Гаррет Вейл.");
const weapon = actor.items.getName("Длинный меч капитана");
if (!weapon) return ui.notifications.warn("Не найден Длинный меч капитана.");
for (let i = 0; i < 2; i++) {
  if (globalThis.MidiQOL?.completeItemUse) await MidiQOL.completeItemUse(weapon, {}, {});
  else if (weapon.use) await weapon.use();
}
